{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A map is unrolled at the edge of the ruined city.",
      "visual_description": "Mara crouches on a cracked cobblestone hill, spreading a hand-drawn map weighted by her brass compass, the ruined skyline of broken towers behind her at dusk.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The clockwork scout returns with news.",
      "visual_description": "Tin Fox trots up the slope, blue glass eyes glinting, key-wind tail still spinning, carrying a scrap of torn royal banner in its jaws.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "The lamp wakes with a warning.",
      "visual_description": "Oracle Lamp's single fiery eye flares inside the glass chimney, throwing long shadows across Mara's ink-stained coat as she lifts it from her satchel.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "A rescuer slips out of a broken window.",
      "visual_description": "Glass Diver emerges headfirst from a shattered shopfront pane as if surfacing from water, his clear helmet catching the city's flickering lights in fractured reflections.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "The team plans the route past the castle gates.",
      "visual_description": "The four gather in an alley while looming iron castle gates rise in the background; Mara points to a chalked line on stone, Tin Fox at her boots, Oracle Lamp glowing on a barrel.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "They find the official who should have helped.",
      "visual_description": "Sleeping Tax Collector slumps against a toll booth with a ledger book pillow under his cheek, stamped papers fluttering from his sleeves in the wind.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "He refuses to wake, even for danger.",
      "visual_description": "Mara shakes the snoring official's shoulder while Tin Fox tugs at his ink-stained ledger; he only mumbles, a stamp falling from his hand.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "An armored patrol marches past the alley.",
      "visual_description": "Shadows of plated figures cross the alley mouth; Glass Diver presses flat against a mirrored window, the patrol's torches reflected across his coat.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "Rumors of a great winged beast drift from the tower.",
      "visual_description": "Oracle Lamp hovers in Mara's hand, its flame stretched toward a distant cursed tower wreathed in red smoke and circling shapes; her face is uncertain.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "The scout finds a hidden way under tattered banners.",
      "visual_description": "Tin Fox squeezes through a gap in a fallen archway draped with faded royal banners, its key-wind tail flicking dust into shafts of moonlight.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "Frightened faces watch from boarded windows.",
      "visual_description": "Pale faces peek through cracks in shuttered houses as Mara passes; Glass Diver kneels to leave a chalk mark on the cobbles, helmet fogged.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "A magic door bars the inner courtyard.",
      "visual_description": "A great brass door etched with glowing sigils blocks the way; Oracle Lamp's eye narrows, reading the runes, while Mara consults her compass which spins wildly.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "The diver passes through the door's mirror panel.",
      "visual_description": "Glass Diver dives headfirst into a silvered panel in the door as if into water, his coat trailing ripples of reflected lantern light.",
      "characters": ["glass_diver", "oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "Inside, the lost one is found in a glass cell.",
      "visual_description": "Glass Diver crouches before a tall glass cell holding Sleeping Tax Collector — the very same dozing official, somehow now also imprisoned here, papers floating around him like leaves.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "The fox slips a key into the lock.",
      "visual_description": "Tin Fox climbs the glass cell, its key-wind tail unscrewing into the lock plate, blue eyes glowing bright as the cell hisses open.",
      "characters": ["tin_fox", "glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "The lamp warns of pursuit closing in.",
      "visual_description": "Oracle Lamp's flame stretches sideways like a pointing finger down a torchlit corridor as Mara hoists the still-drowsy official onto her shoulder.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "They race for the broken bridge at the city's edge.",
      "visual_description": "The team sprints across rain-slick stone toward a crumbling arched bridge over a black river; Tin Fox bounds ahead, Glass Diver carries the snoring official, Mara holds Oracle Lamp high.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "Across the bridge, dawn finds them safe.",
      "visual_description": "On the far bank, Mara unrolls her map under pink dawn light; Tin Fox sits at her feet, Oracle Lamp dims to a contented glow, Glass Diver lowers Sleeping Tax Collector onto soft grass, still snoring.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

